function i(t,n=50){if(!t)return n;try{const e=new URL(t,window.location.origin),r=parseInt(e.searchParams.get("page_size")||"",10);return Number.isFinite(r)&&r>0?r:n}catch{return n}}function a(t,n){if(!t)return null;try{const e=new URL(t,window.location.origin);return e.searchParams.set("page",String(n)),e.toString()}catch{return null}}function o(t,n){return Math.max(1,Math.ceil((t||0)/n))}export{a as b,i as e,o as p};
